18	interface ViolationEvent {
19	  violationType: string;
20	  surface: string;
21	  route: string;
22	  severity: string;
23	  content?: string;
24	}
25	
26	/**
27	 * Record a violation event and update pattern tracking.
28	 * Called after every scan to build the learning model.
29	 */
30	export async function recordViolationPattern(event: ViolationEvent): Promise<void> {
31	  const patternKey = `${event.violationType}::${event.surface}`;
32	  
33	  const db = await getDb();
34	  if (!db) throw new Error('Database not available');
35	  // Check if pattern already exists
36	  const existing = await db.select()
37	    .from(violationPatterns)
38	    .where(
39	      and(
40	        eq(violationPatterns.violationType, event.violationType),
41	        eq(violationPatterns.surface, event.surface),
42	      )
43	    )
44	    .limit(1);
45	  
46	  if (existing.length > 0) {
47	    // Update existing pattern
48	    await db.update(violationPatterns)
49	      .set({
50	        lastSeen: new Date(),
51	        occurrenceCount: sql`${violationPatterns.occurrenceCount} + 1`,
52	        route: event.route, // Update to latest route
53	        avgSeverity: event.severity,
54	        commonContent: event.content?.substring(0, 500) || existing[0].commonContent,
55	        updatedAt: new Date(),
56	      })
57	      .where(eq(violationPatterns.id, existing[0].id));
58	  } else {
59	    // Create new pattern
60	    const patternId = `pat_${Date.now()}_${Math.random().toString(36).substring(2, 8)}`;
61	    await db.insert(violationPatterns).values({
62	      patternId,
63	      violationType: event.violationType,
64	      surface: event.surface,
65	      route: event.route,
66	      occurrenceCount: 1,
67	      avgSeverity: event.severity,
68	      commonContent: event.content?.substring(0, 500),
69	    });
70	  }
71	}
