108	/**
109	 * Batch-record violations from a scan report.
110	 */
111	export async function recordScanViolations(
112	  violations: Array<{ violationType: string; route: string; severity: string; content?: string }>,
113	  surface: string = 'website',
114	): Promise<{ patternsUpdated: number; newPatterns: number }> {
115	  let updated = 0;
116	  let created = 0;
117	  
118	  const db = await getDb();
119	  if (!db) return { patternsUpdated: 0, newPatterns: 0 };
120	  for (const v of violations) {
121	    const existing = await db.select()
122	      .from(violationPatterns)
123	      .where(
124	        and(
125	          eq(violationPatterns.violationType, v.violationType),
126	          eq(violationPatterns.surface, surface),
127	        )
128	      )
129	      .limit(1);
130	    
131	    if (existing.length > 0) {
132	      updated++;
133	    } else {
134	      created++;
135	    }
136	    
137	    await recordViolationPattern({
138	      violationType: v.violationType,
139	      surface,
140	      route: v.route,
141	      severity: v.severity,
142	      content: v.content,
143	    });
144	  }
145	  
146	  return { patternsUpdated: updated, newPatterns: created };
147	}
