149	/**
150	 * Get the top recurring violation patterns across all surfaces.
151	 */
152	export async function getTopPatterns(limit: number = 10): Promise<Array<{
153	  violationType: string;
154	  surface: string;
155	  occurrenceCount: number;
156	  autoFixedCount: number;
157	  manualFixedCount: number;
158	  revertedCount: number;
159	  avgSeverity: string | null;
160	  firstSeen: Date;
161	  lastSeen: Date;
162	  suggestedPrevention: string | null;
163	}>> {
164	  const db = await getDb();
165	  if (!db) return [];
166	  const patterns = await db.select()
167	    .from(violationPatterns)
168	    .orderBy(desc(violationPatterns.occurrenceCount))
169	    .limit(limit);
170	  
171	  return patterns.map(p => ({
172	    violationType: p.violationType,
173	    surface: p.surface,
174	    occurrenceCount: p.occurrenceCount,
175	    autoFixedCount: p.autoFixedCount,
176	    manualFixedCount: p.manualFixedCount,
177	    revertedCount: p.revertedCount,
178	    avgSeverity: p.avgSeverity,
179	    firstSeen: p.firstSeen,
180	    lastSeen: p.lastSeen,
181	    suggestedPrevention: p.suggestedPrevention,
182	  }));
183	}
