397	
398	interface PersonaConfig {
399	  surface: string;
400	  route?: string;
401	  targetPersona: string;
402	  expectedTone?: string;
403	  expectedFormality?: string;
404	  maxReadingLevel?: string;
405	  preferredTerms?: string[];
406	  avoidTerms?: string[];
407	}
408	
409	/**
410	 * Set or update persona alignment for a surface/route.
411	 */
412	export async function setPersonaAlignment(config: PersonaConfig): Promise<string> {
413	  const db = await getDb();
414	  if (!db) return 'Database not available';
415	  const existing = await db.select()
416	    .from(personaAlignmentMap)
417	    .where(
418	      and(
419	        eq(personaAlignmentMap.surface, config.surface),
420	        eq(personaAlignmentMap.targetPersona, config.targetPersona),
421	        config.route
422	          ? eq(personaAlignmentMap.route, config.route)
423	          : sql`${personaAlignmentMap.route} IS NULL`,
424	      )
425	    )
426	    .limit(1);
427	  
428	  if (existing.length > 0) {
429	    await db.update(personaAlignmentMap)
430	      .set({
431	        expectedTone: config.expectedTone || existing[0].expectedTone,
432	        expectedFormality: config.expectedFormality || existing[0].expectedFormality,
433	        maxReadingLevel: config.maxReadingLevel || existing[0].maxReadingLevel,
434	        preferredTerms: config.preferredTerms || existing[0].preferredTerms,
435	        avoidTerms: config.avoidTerms || existing[0].avoidTerms,
436	        updatedAt: new Date(),
437	      })
438	      .where(eq(personaAlignmentMap.id, existing[0].id));
439	    return existing[0].alignmentId;
440	  }
441	  
442	  const alignmentId = `align_${Date.now()}_${Math.random().toString(36).substring(2, 8)}`;
443	  await db.insert(personaAlignmentMap).values({
444	    alignmentId,
445	    surface: config.surface,
446	    route: config.route,
447	    targetPersona: config.targetPersona,
448	    expectedTone: config.expectedTone,
449	    expectedFormality: config.expectedFormality,
450	    maxReadingLevel: config.maxReadingLevel,
451	    preferredTerms: config.preferredTerms,
452	    avoidTerms: config.avoidTerms,
453	  });
454	  
455	  return alignmentId;
456	}
