458	/**
459	 * Get persona alignment config for a specific surface/route.
460	 */
461	export async function getPersonaAlignment(
462	  surface: string,
463	  route?: string,
464	): Promise<Array<{
465	  alignmentId: string;
466	  targetPersona: string;
467	  expectedTone: string | null;
468	  expectedFormality: string | null;
469	  maxReadingLevel: string | null;
470	  preferredTerms: string[] | null;
471	  avoidTerms: string[] | null;
472	  lastAlignmentScore: number | null;
473	}>> {
474	  const db = await getDb();
475	  if (!db) return [];
476	  const conditions = [eq(personaAlignmentMap.surface, surface)];
477	  if (route) {
478	    conditions.push(eq(personaAlignmentMap.route, route));
479	  }
480	  
481	  const alignments = await db.select()
482	    .from(personaAlignmentMap)
483	    .where(and(...conditions)) ;
484	  
485	  if (!Array.isArray(alignments)) return [];
486	  
487	  return alignments.map(a => ({
488	    alignmentId: a.alignmentId,
489	    targetPersona: a.targetPersona,
490	    expectedTone: a.expectedTone,
491	    expectedFormality: a.expectedFormality,
492	    maxReadingLevel: a.maxReadingLevel,
493	    preferredTerms: a.preferredTerms,
494	    avoidTerms: a.avoidTerms,
495	    lastAlignmentScore: a.lastAlignmentScore,
496	  }));
497	}
