499	/**
500	 * Evaluate content against persona alignment using Claude.
501	 */
502	export async function evaluatePersonaAlignment(
503	  content: string,
504	  surface: string,
505	  route?: string,
506	): Promise<{
507	  score: number;
508	  persona: string;
509	  feedback: string;
510	  toneMatch: boolean;
511	  formalityMatch: boolean;
512	}> {
513	  const alignments = await getPersonaAlignment(surface, route);
514	  
515	  if (alignments.length === 0) {
516	    return {
517	      score: 100,
518	      persona: 'unspecified',
519	      feedback: 'No persona alignment configured for this surface.',
520	      toneMatch: true,
521	      formalityMatch: true,
522	    };
523	  }
524	  
525	  const alignment = alignments[0];
526	  
527	  const govResult = await governedGenerate({
528	    messages: [
529	      {
530	        role: 'system',
531	        content: `You are a content alignment evaluator. Evaluate the content against the target persona profile and return JSON.`,
532	      },
533	      {
534	        role: 'user',
535	        content: `Target persona: ${alignment.targetPersona}
536	Expected tone: ${alignment.expectedTone || 'any'}
537	Expected formality: ${alignment.expectedFormality || 'any'}
538	Max reading level: ${alignment.maxReadingLevel || 'any'}
539	Preferred terms: ${(alignment.preferredTerms || []).join(', ') || 'none specified'}
540	Avoid terms: ${(alignment.avoidTerms || []).join(', ') || 'none specified'}
541	
542	Content to evaluate:
543	${content.substring(0, 2000)}
544	
545	Return JSON: { "score": 0-100, "toneMatch": true/false, "formalityMatch": true/false, "feedback": "brief assessment" }`,
546	      },
547	    ],
548	    response_format: {
549	      type: 'json_schema',
550	      json_schema: {
551	        name: 'persona_evaluation',
552	        strict: true,
553	        schema: {
554	          type: 'object',
555	          properties: {
556	            score: { type: 'integer', description: 'Alignment score 0-100' },
557	            toneMatch: { type: 'boolean', description: 'Does tone match expected?' },
558	            formalityMatch: { type: 'boolean', description: 'Does formality match expected?' },
559	            feedback: { type: 'string', description: 'Brief assessment' },
560	          },
561	          required: ['score', 'toneMatch', 'formalityMatch', 'feedback'],
562	          additionalProperties: false,
563	        },
564	      },
565	    },
566	    contentType: 'generation',
567	    contentRole: 'user-facing',
568	    productId: 'services',
569	    surfaceId: 'services-organizational-memory-2',
570	  });
571	  
572	  try {
573	    const rawContent = (govResult as unknown as Record<string, unknown>).choices?.[0]?.message?.content;
574	    const result = JSON.parse(typeof rawContent === 'string' ? rawContent : '{}');
575	    
576	    // Update the alignment score
577	    const dbConn = await getDb();
578	    if (dbConn) await dbConn.update(personaAlignmentMap)
579	      .set({
580	        lastAlignmentScore: result.score,
581	        lastEvaluatedAt: new Date(),
582	        updatedAt: new Date(),
583	      })
584	      .where(eq(personaAlignmentMap.alignmentId, alignment.alignmentId));
585	    
586	    return {
587	      score: result.score || 0,
588	      persona: alignment.targetPersona,
589	      feedback: result.feedback || 'No feedback generated.',
590	      toneMatch: result.toneMatch ?? true,
591	      formalityMatch: result.formalityMatch ?? true,
592	    };
593	  } catch {
594	    return {
595	      score: 50,
596	      persona: alignment.targetPersona,
597	      feedback: 'Evaluation failed — unable to parse govResult.',
598	      toneMatch: true,
599	      formalityMatch: true,
600	    };
601	  }
602	}
